#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""识字卡片插画——方位组（1 字）：中。

字库 note：三个一样的球排一排，正中间那个稍微抬高，两侧球对称放远。
中间球踩在一个小木墩上，抬高看得见；图上不出现任何文字。
"""
import importlib.util
import os

_HERE = os.path.dirname(os.path.abspath(__file__))


def _load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


lib = _load("scys_lib_fangwei", os.path.join(_HERE, "识字卡片_素材库.py"))


def card_zhong():
    g = lib.ground()
    # 小木墩：把中间的球抬起来
    g += lib.R(380 - 76, 352, 152, 94, 18, lib.WOOD)
    g += lib.R(380 - 76, 352 + 94 - 24, 152, 22, 11, lib.WOOD_D)
    g += lib.R(380 - 60, 368, 120, 16, 8, lib.WOOD_L, 0.85)
    # 三个一样的红球：两侧对称放远，正中间抬高
    m, d, h = lib.RED, lib.RED_D, lib.PINK
    g += lib.ball(168, 392, 52, m, d, h)
    g += lib.ball(592, 392, 52, m, d, h)
    g += lib.ball(380, 298, 52, m, d, h)
    return g


# 组卡片文案数据（不含种子字）
GROUP_CARDS = [
    {"char": "中", "pinyin": "zhōng", "tone": "第一声",
     "sentence": "皮球站在正中间。",
     "say": "三个球一样大，站在正中间的是中。",
     "chat": "排队时你站在中间还是两边？",
     "life": "一家三口拍照，你站正中间试试。"},
]


def arts():
    return {"中": card_zhong()}


if __name__ == "__main__":
    import xml.etree.ElementTree as ET

    ziku = _load("scys_ziku_fangwei", os.path.join(_HERE, "识字卡片_字库.py"))
    grp = next(g for g in ziku.GROUPS if g["id"] == "fangwei")
    expect = [it["char"] if isinstance(it, dict) else it for it in grp["chars"]]
    mine = [c["char"] for c in GROUP_CARDS]
    assert mine == expect, f"卡序与字库不一致：{mine} vs {expect}"

    cards = arts()
    assert set(cards) == set(mine), "arts 键与 GROUP_CARDS 不一致"
    punct = "，。！？、；：·—…"
    for c in GROUP_CARDS:
        ch = c["char"]
        core = [t for t in c["sentence"] if t not in punct]
        assert 4 <= len(core) <= 10, f"{ch} sentence 长度 {len(core)}"
        assert ch in c["sentence"], f"{ch} sentence 未含目标字"
        for k in ("say", "chat", "life"):
            assert len(c[k]) <= 30, f"{ch} {k} 超长：{len(c[k])}"
        v = cards[ch]
        ET.fromstring(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 480"><g>{v}</g></svg>')
        for bad in ("<text", "<use", "<defs", "<image", "href"):
            assert bad not in v, f"{ch} 含禁止标记 {bad}"
    print(f"方位组：卡数 {len(GROUP_CARDS)}，arts {len(cards)}，与字库比对一致 ✓")


